        [['LP','LP','LR','LM','LI','LI','RI','RI','RM','RR','RP','RP','RP'], ['LP','LR','LM','LI','LI','RI','RI','RM','RR','RP','RP','RP'], ['LP','LR','LM','LI','LI','RI','RI','RM','RR','RP','RP'], ['LP','LR','LM','LI','LI','RI','RM','RR','RP','RP','RP']]
