    if (!wpm.valid) throw new Error(wpm.message);
    if (!accuracy.valid) throw new Error(accuracy.message);
    if (wpm.value !== null) result.targetWpm = wpm.value;
    if (accuracy.value !== null) result.targetAccuracy = accuracy.value;
