      ' ': 'space',
      '\n': 'new line',
      '\t': 'tab',
      '.': 'period',
      ',': 'comma',
      ';': 'semicolon',
      ':': 'colon',
      "'": 'apostrophe',
      '"': 'quotation mark',
      '?': 'question mark',
      '!': 'exclamation mark',
      '-': 'hyphen',
      '_': 'underscore',
      '/': 'slash',
      '\\': 'backslash',
      '(': 'left parenthesis',
      ')': 'right parenthesis'
